<script setup>import {ref,onMounted} from 'vue';import http from '../api/http';const list=ref([]);const id=ref('');const load=async()=>list.value=(await http.get('/borrow/list')).data.data;const apply=async()=>{await http.post('/borrow/apply',{deviceCode:'DEV-X',lenderHospitalId:21,lenderHospitalName:'第一医院',borrowerHospitalId:22,borrowerHospitalName:'第二医院',operator:'hosp2'});load()};const call=async(url)=>{await http.post(url,{borrowId:id.value,operator:'hosp1'});load()};onMounted(load)</script>
<template><div><h3>借用</h3><button @click='apply'>申请借用</button><input v-model='id' placeholder='borrowId'/><button @click='call("/borrow/approve")'>审批</button><button @click='call("/borrow/lend")'>借出</button><button @click='call("/borrow/receive")'>收到</button><button @click='call("/borrow/return/apply")'>归还申请</button><button @click='call("/borrow/return/confirm")'>归还确认</button><pre>{{list}}</pre></div></template>
